import numpy as np

def oc_update(rho, dc, volfrac, move=0.2):
    lo, hi = 1e-12, 1e12
    while (hi - lo) / (hi + lo) > 1e-9:
        lam = 0.5 * (lo + hi)
        new = np.clip(rho * np.sqrt(-dc / lam), np.maximum(0.0, rho - move), np.minimum(1.0, rho + move))
        if new.mean() > volfrac:
            lo = lam
        else:
            hi = lam
    return new
